94	/**
95	 * The concurrent hash map implementation built by {@link CacheBuilder}.
96	 *
97	 * <p>This implementation is heavily derived from revision 1.96 of <a
98	 * href="http://tinyurl.com/ConcurrentHashMap">ConcurrentHashMap.java</a>.
99	 *
100	 * @author Charles Fry
101	 * @author Bob Lee ({@code com.google.common.collect.MapMaker})
102	 * @author Doug Lea ({@code ConcurrentHashMap})
103	 */
104	@SuppressWarnings({
105	  "GoodTime", // lots of violations (nanosecond math)
106	  "nullness", // too much trouble for the payoff
107	  // All updates of `count` perform their write and any preceding read under the lock.
108	  "NonAtomicVolatileUpdate",
109	})
110	@GwtCompatible
111	@NullUnmarked // TODO(cpovirk): Annotate for nullness.
112	final class LocalCache<K, V> extends AbstractMap<K, V> implements ConcurrentMap<K, V> {
113	
114	  /*
115	   * The basic strategy is to subdivide the table among Segments, each of which itself is a
116	   * concurrently readable hash table. The map supports non-blocking reads and concurrent writes
117	   * across different segments.
118	   *
119	   * If a maximum size is specified, a best-effort bounding is performed per segment, using a
120	   * page-replacement algorithm to determine which entries to evict when the capacity has been
121	   * exceeded.
122	   *
123	   * The page replacement algorithm's data structures are kept casually consistent with the map. The
124	   * ordering of writes to a segment is sequentially consistent. An update to the map and recording
125	   * of reads may not be immediately reflected on the algorithm's data structures. These structures
126	   * are guarded by a lock and operations are applied in batches to avoid lock contention. The
127	   * penalty of applying the batches is spread across threads so that the amortized cost is slightly
128	   * higher than performing just the operation without enforcing the capacity constraint.
129	   *
130	   * This implementation uses a per-segment queue to record a memento of the additions, removals,
131	   * and accesses that were performed on the map. The queue is drained on writes and when it exceeds
132	   * its capacity threshold.
133	   *
134	   * The Least Recently Used page replacement algorithm was chosen due to its simplicity, high hit
135	   * rate, and ability to be implemented with O(1) time complexity. The initial LRU implementation
136	   * operates per-segment rather than globally for increased implementation simplicity. We expect
137	   * the cache hit rate to be similar to that of a global LRU algorithm.
138	   */
139	
140	  // Constants
141	
142	  /**
143	   * The maximum capacity, used if a higher value is implicitly specified by either of the
144	   * constructors with arguments. MUST be a power of two {@code <= 1<<30} to ensure that entries are
145	   * indexable using ints.
146	   */
147	  static final int MAXIMUM_CAPACITY = 1 << 30;
148	
149	  /** The maximum number of segments to allow; used to bound constructor arguments. */
150	  static final int MAX_SEGMENTS = 1 << 16; // slightly conservative
151	
152	  /** Number of (unsynchronized) retries in the containsValue method. */
153	  static final int CONTAINS_VALUE_RETRIES = 3;
154	
155	  /**
156	   * Number of cache access operations that can be buffered per segment before the cache's recency
157	   * ordering information is updated. This is used to avoid lock contention by recording a memento
158	   * of reads and delaying a lock acquisition until the threshold is crossed or a mutation occurs.
159	   *
160	   * <p>This must be a (2^n)-1 as it is used as a mask.
161	   */
162	  static final int DRAIN_THRESHOLD = 0x3F;
163	
164	  /**
165	   * Maximum number of entries to be drained in a single cleanup run. This applies independently to
166	   * the cleanup queue and both reference queues.
167	   */
168	  // TODO(fry): empirically optimize this
169	  static final int DRAIN_MAX = 16;
170	
171	  // Fields
172	
173	  static final Logger logger = Logger.getLogger(LocalCache.class.getName());
174	
175	  /**
176	   * Mask value for indexing into segments. The upper bits of a key's hash code are used to choose
177	   * the segment.
178	   */
179	  final int segmentMask;
180	
181	  /**
182	   * Shift value for indexing within segments. Helps prevent entries that end up in the same segment
183	   * from also ending up in the same bucket.
184	   */
185	  final int segmentShift;
186	
187	  /** The segments, each of which is a specialized hash table. */
188	  final Segment<K, V>[] segments;
189	
190	  /** The concurrency level. */
191	  final int concurrencyLevel;
192	
193	  /** Strategy for comparing keys. */
194	  final Equivalence<Object> keyEquivalence;
195	
196	  /** Strategy for comparing values. */
197	  final Equivalence<Object> valueEquivalence;
198	
199	  /** Strategy for referencing keys. */
200	  final Strength keyStrength;
201	
202	  /** Strategy for referencing values. */
203	  final Strength valueStrength;
204	
205	  /** The maximum weight of this map. UNSET_INT if there is no maximum. */
206	  final long maxWeight;
207	
208	  /** Weigher to weigh cache entries. */
209	  final Weigher<K, V> weigher;
210	
211	  /** How long after the last access to an entry the map will retain that entry. */
212	  final long expireAfterAccessNanos;
213	
214	  /** How long after the last write to an entry the map will retain that entry. */
215	  final long expireAfterWriteNanos;
216	
217	  /** How long after the last write an entry becomes a candidate for refresh. */
218	  final long refreshNanos;
219	
220	  /** Entries waiting to be consumed by the removal listener. */
221	  // TODO(fry): define a new type which creates event objects and automates the clear logic
222	  final Queue<RemovalNotification<K, V>> removalNotificationQueue;
223	
224	  /**
225	   * A listener that is invoked when an entry is removed due to expiration or garbage collection of
226	   * soft/weak entries.
227	   */
228	  final RemovalListener<K, V> removalListener;
229	
230	  /** Measures time in a testable way. */
231	  final Ticker ticker;
232	
233	  /** Factory used to create new entries. */
234	  final EntryFactory entryFactory;
235	
236	  /**
237	   * Accumulates global cache statistics. Note that there are also per-segments stats counters which
238	   * must be aggregated to obtain a global stats view.
239	   */
240	  final StatsCounter globalStatsCounter;
241	
242	  /** The default cache loader to use on loading operations. */
243	  final @Nullable CacheLoader<? super K, V> defaultLoader;
244	
245	  /**
246	   * Creates a new, empty map with the specified strategy, initial capacity and concurrency level.
247	   */
248	  LocalCache(
249	      CacheBuilder<? super K, ? super V> builder, @Nullable CacheLoader<? super K, V> loader) {
250	    concurrencyLevel = min(builder.getConcurrencyLevel(), MAX_SEGMENTS);
251	
252	    keyStrength = builder.getKeyStrength();
253	    valueStrength = builder.getValueStrength();
254	
255	    keyEquivalence = builder.getKeyEquivalence();
256	    valueEquivalence = builder.getValueEquivalence();
257	
258	    maxWeight = builder.getMaximumWeight();
259	    weigher = builder.getWeigher();
260	    expireAfterAccessNanos = builder.getExpireAfterAccessNanos();
261	    expireAfterWriteNanos = builder.getExpireAfterWriteNanos();
262	    refreshNanos = builder.getRefreshNanos();
263	
264	    removalListener = builder.getRemovalListener();
265	    removalNotificationQueue =
266	        (removalListener == NullListener.INSTANCE)
267	            ? discardingQueue()
268	            : new ConcurrentLinkedQueue<>();
269	
270	    ticker = builder.getTicker(recordsTime());
271	    entryFactory = EntryFactory.getFactory(keyStrength, usesAccessEntries(), usesWriteEntries());
272	    globalStatsCounter = builder.getStatsCounterSupplier().get();
273	    defaultLoader = loader;
274	
275	    int initialCapacity = min(builder.getInitialCapacity(), MAXIMUM_CAPACITY);
276	    if (evictsBySize() && !customWeigher()) {
277	      initialCapacity = (int) min(initialCapacity, maxWeight);
278	    }
279	
280	    // Find the lowest power-of-two segmentCount that exceeds concurrencyLevel, unless
281	    // maximumSize/Weight is specified in which case ensure that each segment gets at least 10
282	    // entries. The special casing for size-based eviction is only necessary because that eviction
283	    // happens per segment instead of globally, so too many segments compared to the maximum size
284	    // will result in random eviction behavior.
285	    int segmentShift = 0;
286	    int segmentCount = 1;
287	    while (segmentCount < concurrencyLevel
288	        && (!evictsBySize() || segmentCount * 20L <= maxWeight)) {
289	      ++segmentShift;
290	      segmentCount <<= 1;
291	    }
292	    this.segmentShift = 32 - segmentShift;
293	    segmentMask = segmentCount - 1;
294	
295	    this.segments = newSegmentArray(segmentCount);
296	
297	    int segmentCapacity = initialCapacity / segmentCount;
298	    if (segmentCapacity * segmentCount < initialCapacity) {
299	      ++segmentCapacity;
300	    }
301	
302	    int segmentSize = 1;
303	    while (segmentSize < segmentCapacity) {
304	      segmentSize <<= 1;
305	    }
306	
307	    if (evictsBySize()) {
308	      // Ensure sum of segment max weights = overall max weights
309	      long maxSegmentWeight = maxWeight / segmentCount + 1;
310	      long remainder = maxWeight % segmentCount;
311	      for (int i = 0; i < this.segments.length; ++i) {
312	        if (i == remainder) {
313	          maxSegmentWeight--;
314	        }
315	        this.segments[i] =
316	            createSegment(segmentSize, maxSegmentWeight, builder.getStatsCounterSupplier().get());
317	      }
318	    } else {
319	      for (int i = 0; i < this.segments.length; ++i) {
320	        this.segments[i] =
321	            createSegment(segmentSize, UNSET_INT, builder.getStatsCounterSupplier().get());
322	      }
323	    }
324	  }
325	
326	  boolean evictsBySize() {
327	    return maxWeight >= 0;
328	  }
329	
330	  boolean customWeigher() {
331	    return weigher != OneWeigher.INSTANCE;
332	  }
333	
334	  boolean expires() {
335	    return expiresAfterWrite() || expiresAfterAccess();
336	  }
337	
338	  boolean expiresAfterWrite() {
339	    return expireAfterWriteNanos > 0;
340	  }
341	
342	  boolean expiresAfterAccess() {
343	    return expireAfterAccessNanos > 0;
344	  }
345	
346	  boolean refreshes() {
347	    return refreshNanos > 0;
348	  }
349	
350	  boolean usesAccessQueue() {
351	    return expiresAfterAccess() || evictsBySize();
352	  }
353	
354	  boolean usesWriteQueue() {
355	    return expiresAfterWrite();
356	  }
357	
358	  boolean recordsWrite() {
359	    return expiresAfterWrite() || refreshes();
360	  }
361	
362	  boolean recordsAccess() {
363	    return expiresAfterAccess();
364	  }
365	
366	  boolean recordsTime() {
367	    return recordsWrite() || recordsAccess();
368	  }
369	
370	  boolean usesWriteEntries() {
371	    return usesWriteQueue() || recordsWrite();
372	  }
373	
374	  boolean usesAccessEntries() {
375	    return usesAccessQueue() || recordsAccess();
376	  }
377	
378	  boolean usesKeyReferences() {
379	    return keyStrength != Strength.STRONG;
380	  }
381	
382	  boolean usesValueReferences() {
383	    return valueStrength != Strength.STRONG;
384	  }
385	
386	  enum Strength {
387	    /*
388	     * TODO(kevinb): If we strongly reference the value and aren't loading, we needn't wrap the
389	     * value. This could save ~8 bytes per entry.
390	     */
391	
392	    STRONG {
393	      @Override
394	      <K, V> ValueReference<K, V> referenceValue(
395	          Segment<K, V> segment, ReferenceEntry<K, V> entry, V value, int weight) {
396	        return (weight == 1)
397	            ? new StrongValueReference<K, V>(value)
398	            : new WeightedStrongValueReference<K, V>(value, weight);
399	      }
400	
401	      @Override
402	      Equivalence<Object> defaultEquivalence() {
403	        return Equivalence.equals();
404	      }
405	    },
406	    SOFT {
407	      @Override
408	      <K, V> ValueReference<K, V> referenceValue(
409	          Segment<K, V> segment, ReferenceEntry<K, V> entry, V value, int weight) {
410	        return (weight == 1)
411	            ? new SoftValueReference<K, V>(segment.valueReferenceQueue, value, entry)
412	            : new WeightedSoftValueReference<K, V>(
413	                segment.valueReferenceQueue, value, entry, weight);
414	      }
415	
416	      @Override
417	      Equivalence<Object> defaultEquivalence() {
418	        return Equivalence.identity();
419	      }
420	    },
421	    WEAK {
422	      @Override
423	      <K, V> ValueReference<K, V> referenceValue(
424	          Segment<K, V> segment, ReferenceEntry<K, V> entry, V value, int weight) {
425	        return (weight == 1)
426	            ? new WeakValueReference<K, V>(segment.valueReferenceQueue, value, entry)
427	            : new WeightedWeakValueReference<K, V>(
428	                segment.valueReferenceQueue, value, entry, weight);
429	      }
430	
431	      @Override
432	      Equivalence<Object> defaultEquivalence() {
433	        return Equivalence.identity();
434	      }
435	    };
436	
437	    /** Creates a reference for the given value according to this value strength. */
438	    abstract <K, V> ValueReference<K, V> referenceValue(
439	        Segment<K, V> segment, ReferenceEntry<K, V> entry, V value, int weight);
440	
441	    /**
442	     * Returns the default equivalence strategy used to compare and hash keys or values referenced
443	     * at this strength. This strategy will be used unless the user explicitly specifies an
444	     * alternate strategy.
445	     */
446	    abstract Equivalence<Object> defaultEquivalence();
447	  }
448	
449	  /** Creates new entries. */
450	  enum EntryFactory {
451	    STRONG {
452	      @Override
453	      <K, V> ReferenceEntry<K, V> newEntry(
454	          Segment<K, V> segment, K key, int hash, @Nullable ReferenceEntry<K, V> next) {
455	        return new StrongEntry<>(key, hash, next);
456	      }
457	    },
458	    STRONG_ACCESS {
459	      @Override
460	      <K, V> ReferenceEntry<K, V> newEntry(
461	          Segment<K, V> segment, K key, int hash, @Nullable ReferenceEntry<K, V> next) {
462	        return new StrongAccessEntry<>(key, hash, next);
463	      }
464	
465	      @Override
466	      <K, V> ReferenceEntry<K, V> copyEntry(
467	          Segment<K, V> segment,
468	          ReferenceEntry<K, V> original,
469	          @Nullable ReferenceEntry<K, V> newNext,
470	          K key) {
471	        ReferenceEntry<K, V> newEntry = super.copyEntry(segment, original, newNext, key);
472	        copyAccessEntry(original, newEntry);
473	        return newEntry;
474	      }
475	    },
476	    STRONG_WRITE {
477	      @Override
478	      <K, V> ReferenceEntry<K, V> newEntry(
479	          Segment<K, V> segment, K key, int hash, @Nullable ReferenceEntry<K, V> next) {
480	        return new StrongWriteEntry<>(key, hash, next);
481	      }
482	
483	      @Override
484	      <K, V> ReferenceEntry<K, V> copyEntry(
485	          Segment<K, V> segment,
486	          ReferenceEntry<K, V> original,
487	          @Nullable ReferenceEntry<K, V> newNext,
488	          K key) {
489	        ReferenceEntry<K, V> newEntry = super.copyEntry(segment, original, newNext, key);
490	        copyWriteEntry(original, newEntry);
491	        return newEntry;
492	      }
493	    },
494	    STRONG_ACCESS_WRITE {
495	      @Override
496	      <K, V> ReferenceEntry<K, V> newEntry(
497	          Segment<K, V> segment, K key, int hash, @Nullable ReferenceEntry<K, V> next) {
498	        return new StrongAccessWriteEntry<>(key, hash, next);
499	      }
500	
501	      @Override
502	      <K, V> ReferenceEntry<K, V> copyEntry(
503	          Segment<K, V> segment,
504	          ReferenceEntry<K, V> original,
505	          @Nullable ReferenceEntry<K, V> newNext,
506	          K key) {
507	        ReferenceEntry<K, V> newEntry = super.copyEntry(segment, original, newNext, key);
508	        copyAccessEntry(original, newEntry);
509	        copyWriteEntry(original, newEntry);
510	        return newEntry;
511	      }
512	    },
513	    WEAK {
514	      @Override
515	      <K, V> ReferenceEntry<K, V> newEntry(
516	          Segment<K, V> segment, K key, int hash, @Nullable ReferenceEntry<K, V> next) {
517	        return new WeakEntry<>(segment.keyReferenceQueue, key, hash, next);
518	      }
519	    },
520	    WEAK_ACCESS {
521	      @Override
522	      <K, V> ReferenceEntry<K, V> newEntry(
523	          Segment<K, V> segment, K key, int hash, @Nullable ReferenceEntry<K, V> next) {
524	        return new WeakAccessEntry<>(segment.keyReferenceQueue, key, hash, next);
525	      }
526	
527	      @Override
528	      <K, V> ReferenceEntry<K, V> copyEntry(
529	          Segment<K, V> segment,
530	          ReferenceEntry<K, V> original,
531	          @Nullable ReferenceEntry<K, V> newNext,
532	          K key) {
533	        ReferenceEntry<K, V> newEntry = super.copyEntry(segment, original, newNext, key);
534	        copyAccessEntry(original, newEntry);
535	        return newEntry;
536	      }
537	    },
538	    WEAK_WRITE {
539	      @Override
540	      <K, V> ReferenceEntry<K, V> newEntry(
541	          Segment<K, V> segment, K key, int hash, @Nullable ReferenceEntry<K, V> next) {
542	        return new WeakWriteEntry<>(segment.keyReferenceQueue, key, hash, next);
543	      }
544	
545	      @Override
546	      <K, V> ReferenceEntry<K, V> copyEntry(
547	          Segment<K, V> segment,
548	          ReferenceEntry<K, V> original,
549	          @Nullable ReferenceEntry<K, V> newNext,
550	          K key) {
551	        ReferenceEntry<K, V> newEntry = super.copyEntry(segment, original, newNext, key);
552	        copyWriteEntry(original, newEntry);
553	        return newEntry;
554	      }
555	    },
556	    WEAK_ACCESS_WRITE {
557	      @Override
558	      <K, V> ReferenceEntry<K, V> newEntry(
559	          Segment<K, V> segment, K key, int hash, @Nullable ReferenceEntry<K, V> next) {
560	        return new WeakAccessWriteEntry<>(segment.keyReferenceQueue, key, hash, next);
561	      }
562	
563	      @Override
564	      <K, V> ReferenceEntry<K, V> copyEntry(
565	          Segment<K, V> segment,
566	          ReferenceEntry<K, V> original,
567	          @Nullable ReferenceEntry<K, V> newNext,
568	          K key) {
569	        ReferenceEntry<K, V> newEntry = super.copyEntry(segment, original, newNext, key);
570	        copyAccessEntry(original, newEntry);
571	        copyWriteEntry(original, newEntry);
572	        return newEntry;
573	      }
574	    };
575	
576	    // Masks used to compute indices in the following table.
577	
578	    static final int ACCESS_MASK = 1;
579	    static final int WRITE_MASK = 2;
580	    static final int WEAK_MASK = 4;
581	
582	    /** Look-up table for factories. */
583	    static final EntryFactory[] factories = {
584	      STRONG,
585	      STRONG_ACCESS,
586	      STRONG_WRITE,
587	      STRONG_ACCESS_WRITE,
588	      WEAK,
589	      WEAK_ACCESS,
590	      WEAK_WRITE,
591	      WEAK_ACCESS_WRITE,
592	    };
593	
594	    static EntryFactory getFactory(
595	        Strength keyStrength, boolean usesAccessQueue, boolean usesWriteQueue) {
596	      int flags =
597	          ((keyStrength == Strength.WEAK) ? WEAK_MASK : 0)
598	              | (usesAccessQueue ? ACCESS_MASK : 0)
599	              | (usesWriteQueue ? WRITE_MASK : 0);
600	      return factories[flags];
601	    }
602	
603	    /**
604	     * Creates a new entry.
605	     *
606	     * @param segment to create the entry for
607	     * @param key of the entry
608	     * @param hash of the key
609	     * @param next entry in the same bucket
610	     */
611	    abstract <K, V> ReferenceEntry<K, V> newEntry(
612	        Segment<K, V> segment, K key, int hash, @Nullable ReferenceEntry<K, V> next);
613	
614	    /**
615	     * Copies an entry, assigning it a new {@code next} entry.
616	     *
617	     * @param original the entry to copy. But avoid calling {@code getKey} on it: Instead, use the
618	     *     {@code key} parameter. That way, we prevent the key from being garbage collected in the
619	     *     case of weak keys. If we create a new entry with a key that is null at construction time,
620	     *     we're not sure if entry will necessarily ever be garbage collected.
621	     * @param newNext entry in the same bucket
