1679	  /**
1680	   * Applies a supplemental hash function to a given hash code, which defends against poor quality
1681	   * hash functions. This is critical when the concurrent hash map uses power-of-two length hash
1682	   * tables, that otherwise encounter collisions for hash codes that do not differ in lower or upper
1683	   * bits.
1684	   *
1685	   * @param h hash code
1686	   */
1687	  static int rehash(int h) {
1688	    // Spread bits to regularize both segment and index locations,
1689	    // using variant of single-word Wang/Jenkins hash.
1690	    // TODO(kevinb): use Hashing/move this to Hashing?
1691	    h += (h << 15) ^ 0xffffcd7d;
1692	    h ^= h >>> 10;
1693	    h += h << 3;
1694	    h ^= h >>> 6;
1695	    h += (h << 2) + (h << 14);
1696	    return h ^ (h >>> 16);
1697	  }
