1862	  /**
1863	   * Segments are specialized versions of hash tables. This subclass inherits from ReentrantLock
1864	   * opportunistically, just to simplify some locking and avoid separate construction.
1865	   */
1866	  @SuppressWarnings("serial") // This class is never serialized.
1867	  static final class Segment<K, V> extends ReentrantLock {
1868	
1869	    /*
1870	     * TODO(fry): Consider copying variables (like evictsBySize) from outer class into this class.
1871	     * It will require more memory but will reduce indirection.
1872	     */
1873	
1874	    /*
1875	     * Segments maintain a table of entry lists that are ALWAYS kept in a consistent state, so can
1876	     * be read without locking. Next fields of nodes are immutable (final). All list additions are
1877	     * performed at the front of each bin. This makes it easy to check changes, and also fast to
1878	     * traverse. When nodes would otherwise be changed, new nodes are created to replace them. This
1879	     * works well for hash tables since the bin lists tend to be short. (The average length is less
1880	     * than two.)
1881	     *
1882	     * Read operations can thus proceed without locking, but rely on selected uses of volatiles to
1883	     * ensure that completed write operations performed by other threads are noticed. For most
1884	     * purposes, the "count" field, tracking the number of elements, serves as that volatile
1885	     * variable ensuring visibility. This is convenient because this field needs to be read in many
1886	     * read operations anyway:
1887	     *
1888	     * - All (unsynchronized) read operations must first read the "count" field, and should not look
1889	     * at table entries if it is 0.
1890	     *
1891	     * - All (synchronized) write operations should write to the "count" field after structurally
1892	     * changing any bin. The operations must not take any action that could even momentarily cause a
1893	     * concurrent read operation to see inconsistent data. This is made easier by the nature of the
1894	     * read operations in Map. For example, no operation can reveal that the table has grown but the
1895	     * threshold has not yet been updated, so there are no atomicity requirements for this with
1896	     * respect to reads.
1897	     *
1898	     * As a guide, all critical volatile reads and writes to the count field are marked in code
1899	     * comments.
1900	     */
1901	
1902	    @Weak final LocalCache<K, V> map;
1903	
1904	    /** The number of live elements in this segment's region. */
1905	    volatile int count;
1906	
1907	    /** The weight of the live elements in this segment's region. */
1908	    @GuardedBy("this")
1909	    long totalWeight;
1910	
1911	    /**
1912	     * Number of updates that alter the size of the table. This is used during bulk-read methods to
1913	     * make sure they see a consistent snapshot: If modCounts change during a traversal of segments
1914	     * loading size or checking containsValue, then we might have an inconsistent view of state so
1915	     * (usually) must retry.
1916	     */
1917	    int modCount;
1918	
1919	    /**
1920	     * The table is expanded when its size exceeds this threshold. (The value of this field is
1921	     * always {@code (int) (capacity * 0.75)}.)
1922	     */
1923	    int threshold;
1924	
1925	    /** The per-segment table. */
1926	    volatile @Nullable AtomicReferenceArray<ReferenceEntry<K, V>> table;
1927	
1928	    /** The maximum weight of this segment. UNSET_INT if there is no maximum. */
1929	    final long maxSegmentWeight;
1930	
1931	    /**
1932	     * The key reference queue contains entries whose keys have been garbage collected, and which
1933	     * need to be cleaned up internally.
1934	     */
1935	    final @Nullable ReferenceQueue<K> keyReferenceQueue;
1936	
1937	    /**
1938	     * The value reference queue contains value references whose values have been garbage collected,
1939	     * and which need to be cleaned up internally.
1940	     */
1941	    final @Nullable ReferenceQueue<V> valueReferenceQueue;
1942	
1943	    /**
1944	     * The recency queue is used to record which entries were accessed for updating the access
1945	     * list's ordering. It is drained as a batch operation when either the DRAIN_THRESHOLD is
1946	     * crossed or a write occurs on the segment.
1947	     */
1948	    final Queue<ReferenceEntry<K, V>> recencyQueue;
1949	
1950	    /**
1951	     * A counter of the number of reads since the last write, used to drain queues on a small
1952	     * fraction of read operations.
1953	     */
1954	    final AtomicInteger readCount = new AtomicInteger();
1955	
1956	    /**
1957	     * A queue of elements currently in the map, ordered by write time. Elements are added to the
1958	     * tail of the queue on write.
1959	     */
1960	    @GuardedBy("this")
1961	    final Queue<ReferenceEntry<K, V>> writeQueue;
1962	
1963	    /**
1964	     * A queue of elements currently in the map, ordered by access time. Elements are added to the
1965	     * tail of the queue on access (note that writes count as accesses).
1966	     */
1967	    @GuardedBy("this")
1968	    final Queue<ReferenceEntry<K, V>> accessQueue;
1969	
1970	    /** Accumulates cache statistics. */
1971	    final StatsCounter statsCounter;
1972	
1973	    Segment(
1974	        LocalCache<K, V> map,
1975	        int initialCapacity,
1976	        long maxSegmentWeight,
1977	        StatsCounter statsCounter) {
1978	      this.map = map;
1979	      this.maxSegmentWeight = maxSegmentWeight;
1980	      this.statsCounter = checkNotNull(statsCounter);
1981	      initTable(newEntryArray(initialCapacity));
1982	
1983	      keyReferenceQueue = map.usesKeyReferences() ? new ReferenceQueue<>() : null;
1984	
1985	      valueReferenceQueue = map.usesValueReferences() ? new ReferenceQueue<>() : null;
1986	
1987	      recencyQueue = map.usesAccessQueue() ? new ConcurrentLinkedQueue<>() : discardingQueue();
1988	
1989	      writeQueue = map.usesWriteQueue() ? new WriteQueue<>() : discardingQueue();
1990	
1991	      accessQueue = map.usesAccessQueue() ? new AccessQueue<>() : discardingQueue();
1992	    }
