2113	    V lockedGetOrLoad(K key, int hash, CacheLoader<? super K, V> loader) throws ExecutionException {
2114	      ReferenceEntry<K, V> e;
2115	      ValueReference<K, V> valueReference = null;
2116	      LoadingValueReference<K, V> loadingValueReference = null;
2117	      boolean createNewEntry = true;
2118	
2119	      lock();
2120	      try {
2121	        // re-read ticker once inside the lock
2122	        long now = map.ticker.read();
2123	        preWriteCleanup(now);
2124	
2125	        int newCount = this.count - 1;
2126	        AtomicReferenceArray<ReferenceEntry<K, V>> table = this.table;
2127	        int index = hash & (table.length() - 1);
2128	        ReferenceEntry<K, V> first = table.get(index);
2129	
2130	        for (e = first; e != null; e = e.getNext()) {
2131	          K entryKey = e.getKey();
2132	          if (e.getHash() == hash
2133	              && entryKey != null
2134	              && map.keyEquivalence.equivalent(key, entryKey)) {
2135	            valueReference = e.getValueReference();
2136	            if (valueReference.isLoading()) {
2137	              createNewEntry = false;
2138	            } else {
