2145	                // entries, but let's accommodate an incorrect expiration queue.
2146	                enqueueNotification(
2147	                    entryKey, hash, value, valueReference.getWeight(), RemovalCause.EXPIRED);
2148	              } else {
2149	                recordLockedRead(e, now);
2150	                statsCounter.recordHits(1);
