2152	                return value;
2153	              }
2154	
2155	              // immediately reuse invalid entries
2156	              writeQueue.remove(e);
2157	              accessQueue.remove(e);
2158	              this.count = newCount; // write-volatile
2159	            }
2160	            break;
2161	          }
2162	        }
2163	
2164	        if (createNewEntry) {
2165	          loadingValueReference = new LoadingValueReference<>();
2166	
2167	          if (e == null) {
2168	            e = newEntry(key, hash, first);
2169	            e.setValueReference(loadingValueReference);
2170	            table.set(index, e);
2171	          } else {
2172	            e.setValueReference(loadingValueReference);
2173	          }
2174	        }
2175	      } finally {
2176	        unlock();
2177	        postWriteCleanup();
2178	      }
