2182	          // Synchronizes on the entry to allow failing fast when a recursive load is
2183	          // detected. This may be circumvented when an entry is copied, but will fail fast most
2184	          // of the time.
2185	          synchronized (e) {
2186	            return loadSync(key, hash, loadingValueReference, loader);
2187	          }
