2197	    V waitForLoadingValue(ReferenceEntry<K, V> e, K key, ValueReference<K, V> valueReference)
2198	        throws ExecutionException {
2199	      if (!valueReference.isLoading()) {
2200	        throw new AssertionError();
2201	      }
2202	
2203	      checkState(!Thread.holdsLock(e), "Recursive load of: %s", key);
