2221	        int hash,
2222	        BiFunction<? super K, ? super @Nullable V, ? extends @Nullable V> function) {
2223	      ReferenceEntry<K, V> e;
2224	      ValueReference<K, V> valueReference = null;
2225	      ComputingValueReference<K, V> computingValueReference = null;
2226	      boolean createNewEntry = true;
2227	      V newValue;
2228	
2229	      lock();
2230	      try {
2231	        // re-read ticker once inside the lock
2232	        long now = map.ticker.read();
2233	        preWriteCleanup(now);
2234	
2235	        AtomicReferenceArray<ReferenceEntry<K, V>> table = this.table;
2236	        int index = hash & (table.length() - 1);
2237	        ReferenceEntry<K, V> first = table.get(index);
2238	
2239	        for (e = first; e != null; e = e.getNext()) {
2240	          K entryKey = e.getKey();
2241	          if (e.getHash() == hash
2242	              && entryKey != null
2243	              && map.keyEquivalence.equivalent(key, entryKey)) {
2244	            valueReference = e.getValueReference();
2245	            if (map.isExpired(e, now)) {
2246	              // This is a duplicate check, as preWriteCleanup already purged expired
2247	              // entries, but let's accommodate an incorrect expiration queue.
2248	              enqueueNotification(
2249	                  entryKey,
2250	                  hash,
2251	                  valueReference.get(),
2252	                  valueReference.getWeight(),
2253	                  RemovalCause.EXPIRED);
